export type TaskLedgerEventType =
  | 'task.submitted'
  | 'task.accepted'
  | 'task.rejected'
  | 'task.completed'
  | 'task.cancelled'
  | string;

export interface TaskLedgerEvent<TPayload = Record<string, unknown>> {
  eventId?: string;
  workspaceId: string;
  batchIdempotencyKey?: string;
  type: TaskLedgerEventType;
  payload: TPayload;
  timestamp?: string;
}

export interface WorkingContextTask {
  taskId: string;
  workspaceId: string;
  status: 'pending' | 'accepted' | 'rejected' | 'completed' | 'cancelled';
  batchIdempotencyKey?: string;
  payload: Record<string, unknown>;
  updatedAt: string;
}

export interface WorkingContextView {
  workspaceId: string;
  tasks: WorkingContextTask[];
  pending: WorkingContextTask[];
  accepted: WorkingContextTask[];
  events: TaskLedgerEvent[];
}

export interface TaskLedgerAppendOptions {
  batchIdempotencyKey?: string;
  eventId?: string;
  timestamp?: string;
}

export interface TaskLedgerReadOptions {
  workspaceId?: string;
}

export function taskIdFromPayload(payload: Record<string, unknown>): string {
  const value = payload.taskId ?? payload.id;
  return typeof value === 'string' ? value : '';
}

export function statusForTaskEvent(type: string): WorkingContextTask['status'] | undefined {
  switch (type) {
    case 'task.submitted':
      return 'pending';
    case 'task.accepted':
      return 'accepted';
    case 'task.rejected':
      return 'rejected';
    case 'task.completed':
      return 'completed';
    case 'task.cancelled':
      return 'cancelled';
    default:
      return undefined;
  }
}

export function projectTaskLedgerEvents(
  workspaceId: string,
  events: readonly TaskLedgerEvent[],
): WorkingContextView {
  const scoped = events.filter((event) => event.workspaceId === workspaceId);
  const tasks = new Map<string, WorkingContextTask>();

  for (const event of scoped) {
    const status = statusForTaskEvent(event.type);
    if (!status) continue;
    const taskId = taskIdFromPayload(event.payload ?? {}) || event.eventId || '';
    if (!taskId) continue;
    const previous = tasks.get(taskId);
    tasks.set(taskId, {
      taskId,
      workspaceId,
      status,
      batchIdempotencyKey: event.batchIdempotencyKey ?? previous?.batchIdempotencyKey,
      payload: { ...(previous?.payload ?? {}), ...(event.payload ?? {}) },
      updatedAt: event.timestamp ?? previous?.updatedAt ?? '',
    });
  }

  const projected = [...tasks.values()].sort((a, b) =>
    a.taskId.localeCompare(b.taskId) || a.updatedAt.localeCompare(b.updatedAt),
  );
  return {
    workspaceId,
    tasks: projected,
    pending: projected.filter((task) => task.status === 'pending'),
    accepted: projected.filter((task) => task.status === 'accepted'),
    events: scoped,
  };
}

import { appendFile, mkdir, readFile, stat } from 'node:fs/promises';
import path from 'node:path';
import {
  projectTaskLedgerEvents,
  taskIdFromPayload,
  type TaskLedgerAppendOptions,
  type TaskLedgerEvent,
  type TaskLedgerReadOptions,
  type WorkingContextView,
} from '../../shared/task-ledger-working-context';

export * from '../../shared/task-ledger-working-context';

export const TASK_LEDGER_FILE_NAME = 'task-ledger.jsonl';

export interface TaskLedgerLocation {
  /** Directory containing the workspace's task-ledger.jsonl file. */
  ledgerDirectory: string;
  /** Optional root used when a caller wants workspace isolation. */
  ledgerRoot?: string;
}

export interface AppendTaskLedgerEventOptions extends TaskLedgerLocation, TaskLedgerAppendOptions {
  workspaceId: string;
  type: string;
  payload: Record<string, unknown>;
}

function workspaceDirectoryName(workspaceId: string): string {
  const safe = workspaceId.replace(/[^a-zA-Z0-9._-]/g, '_');
  let hash = 2166136261;
  for (let index = 0; index < workspaceId.length; index += 1) {
    hash ^= workspaceId.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${safe || 'workspace'}-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

export function resolveTaskLedgerDirectory(location: TaskLedgerLocation | string, workspaceId?: string): string {
  if (typeof location === 'string') return location;
  if (!location.ledgerRoot) return location.ledgerDirectory;
  if (!workspaceId) throw new Error('workspaceId is required when ledgerRoot is used');
  return path.join(location.ledgerRoot, workspaceDirectoryName(workspaceId));
}

export function taskLedgerPath(location: TaskLedgerLocation | string, workspaceId?: string): string {
  return path.join(resolveTaskLedgerDirectory(location, workspaceId), TASK_LEDGER_FILE_NAME);
}

function normalizeEvent(
  workspaceId: string,
  type: string,
  payload: Record<string, unknown>,
  options: TaskLedgerAppendOptions = {},
): TaskLedgerEvent {
  return {
    eventId: options.eventId ?? `${Date.now()}-${Math.random().toString(16).slice(2)}`,
    workspaceId,
    batchIdempotencyKey: options.batchIdempotencyKey,
    type,
    payload,
    timestamp: options.timestamp ?? new Date().toISOString(),
  };
}

async function readLedgerFile(file: string): Promise<TaskLedgerEvent[]> {
  let contents: string;
  try {
    contents = await readFile(file, 'utf8');
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw error;
  }

  const events: TaskLedgerEvent[] = [];
  for (const line of contents.split(/\r?\n/)) {
    if (!line.trim()) continue;
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      continue;
    }
    if (!parsed || typeof parsed !== 'object') continue;
    const event = parsed as Partial<TaskLedgerEvent>;
    if (typeof event.workspaceId !== 'string' || typeof event.type !== 'string') continue;
    events.push({
      ...event,
      payload:
        event.payload && typeof event.payload === 'object'
          ? (event.payload as Record<string, unknown>)
          : {},
    });
  }
  return events;
}

export async function readTaskLedger(
  location: TaskLedgerLocation | string,
  workspaceId?: string,
  options: TaskLedgerReadOptions = {},
): Promise<TaskLedgerEvent[]> {
  const file = taskLedgerPath(location, workspaceId);
  const events = await readLedgerFile(file);
  const scope = options.workspaceId ?? workspaceId;
  return scope ? events.filter((event) => event.workspaceId === scope) : events;
}

export async function appendTaskLedgerEvent(
  options: AppendTaskLedgerEventOptions,
): Promise<TaskLedgerEvent>;
export async function appendTaskLedgerEvent(
  location: TaskLedgerLocation | string,
  workspaceId: string,
  type: string,
  payload: Record<string, unknown>,
  options?: TaskLedgerAppendOptions,
): Promise<TaskLedgerEvent>;
export async function appendTaskLedgerEvent(
  locationOrOptions: TaskLedgerLocation | string | AppendTaskLedgerEventOptions,
  workspaceId?: string,
  type?: string,
  payload?: Record<string, unknown>,
  options: TaskLedgerAppendOptions = {},
): Promise<TaskLedgerEvent> {
  const isOptions =
    typeof locationOrOptions === 'object' &&
    locationOrOptions !== null &&
    'workspaceId' in locationOrOptions &&
    'type' in locationOrOptions;
  const location = isOptions ? locationOrOptions : (locationOrOptions as TaskLedgerLocation | string);
  const scope = isOptions ? locationOrOptions.workspaceId : workspaceId;
  const eventType = isOptions ? locationOrOptions.type : type;
  const eventPayload = isOptions ? locationOrOptions.payload : payload;
  const eventOptions = isOptions ? locationOrOptions : options;

  if (!scope) throw new Error('workspaceId is required');
  if (!eventType) throw new Error('event type is required');

  const directory = resolveTaskLedgerDirectory(location, scope);
  const file = path.join(directory, TASK_LEDGER_FILE_NAME);
  const existing = await readLedgerFile(file);
  const key = eventOptions.batchIdempotencyKey;
  if (key) {
    const duplicate = existing.find(
      (event) =>
        event.workspaceId === scope && event.batchIdempotencyKey === key,
    );
    if (duplicate) return duplicate;
  }

  const event = normalizeEvent(scope, eventType, eventPayload ?? {}, eventOptions);
  await mkdir(directory, { recursive: true });
  await appendFile(file, `${JSON.stringify(event)}\n`, { encoding: 'utf8', flag: 'a' });
  return event;
}

export async function projectWorkingContext(
  location: TaskLedgerLocation | string,
  workspaceId: string,
): Promise<WorkingContextView> {
  const events = await readTaskLedger(location, workspaceId);
  return projectTaskLedgerEvents(workspaceId, events);
}

export class TaskLedgerWorkingContext {
  constructor(
    private readonly location: TaskLedgerLocation | string,
    private readonly workspaceId: string,
  ) {}

  append(
    type: string,
    payload: Record<string, unknown>,
    options: TaskLedgerAppendOptions = {},
  ): Promise<TaskLedgerEvent> {
    return appendTaskLedgerEvent(
      this.location,
      this.workspaceId,
      type,
      payload,
      options,
    );
  }

  read(): Promise<TaskLedgerEvent[]> {
    return readTaskLedger(this.location, this.workspaceId);
  }

  project(): Promise<WorkingContextView> {
    return projectWorkingContext(this.location, this.workspaceId);
  }
}

export const readWorkingContext = readTaskLedger;
export const projectTaskLedger = projectTaskLedgerEvents;

